    public static void addValue(MethodName _filterName, Name _filterFieldName, Name _fieldAttributeName, str _value)
    {
        TFMFilterFieldValues fieldValue;
        ttsbegin;
        select firstonly forupdate fieldValue where fieldValue.FilterName == _filterName && fieldValue.FilterFieldName == _filterFieldName && fieldValue.FilterAttributeName == _fieldAttributeName;

        fieldValue.FilterName = _filterName;
        fieldValue.FilterFieldName = _filterFieldName;
        fieldValue.FilterAttributeName = _fieldAttributeName;
        fieldValue.Value = _value;
        if (fieldValue.RecId)
        {
            fieldValue.update();
        }
		else
        {
            fieldValue.insert();
        }
        ttscommit;
    }

public static str getValue(MethodName _filterName, Name _filterFieldName, Name _fieldAttributeName)
{
    TFMFilterFieldValues fieldValue;

    select firstonly fieldValue where fieldValue.FilterName == _filterName && fieldValue.FilterFieldName == _filterFieldName && fieldValue.FilterAttributeName == _fieldAttributeName;
    return fieldValue.Value;

}

    public static void addSavedValuesToCollector(MethodName _filterName, Name _filterFieldName, TFMRegistrationCollector	_collector)
    {
        TFMFilterFieldValues fieldValue;
        anytype             convertedValue;
        SysDictMethod       sdm;
        SysDictClass		sdc;
        Types               baseType;

        while select fieldValue where fieldValue.FilterName == _filterName && fieldValue.FilterFieldName == _filterFieldName
        {
            sdc = new SysDictClass(classIdGet(_collector));
		    if (SysTest::hasMethod(_collector, 'parm' + fieldValue.FilterAttributeName))
            {
                sdm = new SysDictMethod(UtilElementType::ClassInstanceMethod,sdc.id(),'parm'+ fieldValue.FilterAttributeName);

                baseType = sdm.returnType();
                if (baseType == Types::UserType && sdm.returnTypeName())
                {
                    baseType = new DictType(extendedTypeName2Id(sdm.returnTypeName())).baseType();
                }
                convertedValue = TFMDocCustomFunctionFlow::ConvertToType(fieldValue.Value, baseType,baseType != Types::Enum ? extendedTypeId2name(sdm.returnId()) : enumId2Name(sdm.returnId()) );
                sdc.callObject('parm' + fieldValue.FilterAttributeName,_collector,convertedValue);
            }
        }

    }
